"""Pure functions for interpreting Digitransit stop-time records."""

from datetime import datetime, timezone
from zoneinfo import ZoneInfo

from .const import (
    ALL,
    DICT_KEY_ARRIVAL,
    DICT_KEY_DEST,
    DICT_KEY_ROUTE,
    DICT_KEY_ROUTES,
    STOP_CODE,
    STOP_GTFS,
    STOP_NAME,
)

HELSINKI = ZoneInfo("Europe/Helsinki")
CANCELED_STATES = {"CANCELED", "CANCELLED"}


def base_unique_id(gtfs_id: str, route: str | None = None, dest: str | None = None) -> str:
    """Retain the unique IDs generated by the original integration."""
    if route and route.lower() != ALL:
        return f"{gtfs_id} {route.upper()}"
    if dest and dest.lower() != ALL:
        return f"{gtfs_id} {dest.upper()}"
    return f"{gtfs_id} ALL"


def select_stop(stops: list[dict], requested: str) -> dict | None:
    """Prefer an exact GTFS ID/public code/name over substring search results."""
    normalized = requested.strip().casefold()
    if not normalized:
        return None
    for field in ("gtfsId", "code", "name"):
        for stop in stops:
            if str(stop.get(field) or "").casefold() == normalized:
                return stop
    return stops[0] if stops else None


def route_matches(stop: dict, route: str, destination: str) -> bool:
    """Validate route/destination against patterns provided for the stop."""
    patterns = stop.get("patterns") or []
    if route.casefold() != ALL:
        return any(
            (pattern.get("route") or {}).get("shortName", "").casefold()
            == route.casefold()
            for pattern in patterns
            if isinstance(pattern, dict)
        )
    if destination.casefold() != ALL:
        return any(
            destination.casefold() in (pattern.get("headsign") or "").casefold()
            for pattern in patterns
            if isinstance(pattern, dict)
        )
    return True


def parse_departures(
    stop: dict,
    route_filter: str = ALL,
    destination_filter: str = ALL,
    route_filters: list[str] | None = None,
) -> dict:
    """Convert serviceDay-relative times to local Helsinki arrival times.

    Digitransit times can be greater than 86400, or negative, around midnight.
    The full Unix timestamp must be computed *before* local formatting.
    """
    if not isinstance(stop, dict):
        raise ValueError("Invalid stop response")

    routes = []
    for item in stop.get("stoptimesWithoutPatterns") or []:
        if not isinstance(item, dict):
            continue
        if str(item.get("realtimeState") or "").upper() in CANCELED_STATES:
            continue

        trip = item.get("trip") or {}
        route_info = trip.get("route") or {}
        route = (route_info.get("shortName") or "").strip()
        mode = route_info.get("mode")
        vehicle_mode = mode.upper() if isinstance(mode, str) and mode else None
        destination = (item.get("headsign") or "").strip()
        if not route:
            continue
        if route_filters is not None:
            selected = {name.casefold() for name in route_filters}
            if selected and route.casefold() not in selected:
                continue
            if not selected and destination_filter.casefold() != ALL:
                if destination_filter.casefold() not in destination.casefold():
                    continue
        elif route_filter and route_filter.casefold() != ALL:
            if route.casefold() != route_filter.casefold():
                continue
        elif destination_filter and destination_filter.casefold() != ALL:
            if destination_filter.casefold() not in destination.casefold():
                continue

        service_day = item.get("serviceDay")
        scheduled = item.get("scheduledArrival")
        if service_day is None or scheduled is None:
            continue
        if not isinstance(service_day, int) or not isinstance(scheduled, int):
            continue
        realtime = item.get("realtime") is True
        predicted = item.get("realtimeArrival")
        if realtime and isinstance(predicted, int):
            arrival_offset = predicted
        else:
            realtime = False
            arrival_offset = scheduled
        arrival_timestamp = service_day + arrival_offset
        arrival_dt = datetime.fromtimestamp(arrival_timestamp, tz=timezone.utc)
        # HFP identifies a *journey* by GTFS route ID, direction,
        # operating day and first-stop scheduled departure. These values
        # are intentionally separate from the public route number.
        departure_stoptime = trip.get("departureStoptime") or {}
        route_gtfs_id = (trip.get("route") or {}).get("gtfsId")
        direction_id = trip.get("directionId")
        first_service_day = departure_stoptime.get("serviceDay")
        first_departure = departure_stoptime.get("scheduledDeparture")
        if (
            isinstance(first_service_day, int)
            and isinstance(first_departure, int)
            and isinstance(route_gtfs_id, str)
            and route_gtfs_id.startswith("HSL:")
            and str(direction_id) in ("0", "1")
        ):
            first_start = datetime.fromtimestamp(
                first_service_day + first_departure, tz=timezone.utc
            ).astimezone(HELSINKI)
            operation_day = datetime.fromtimestamp(
                first_service_day, tz=timezone.utc
            ).astimezone(HELSINKI).date().isoformat()
            hfp_route = route_gtfs_id.split(":", 1)[1]
            hfp_direction = str(int(direction_id) + 1)
            hfp_start = first_start.strftime("%H:%M")
        else:
            hfp_route = hfp_direction = hfp_start = operation_day = None

        routes.append(
            {
                "vehicle_mode": vehicle_mode,
                "hfp_route_id": hfp_route,
                "hfp_direction": hfp_direction,
                "hfp_start": hfp_start,
                "hfp_operating_day": operation_day,
                DICT_KEY_ROUTE: route,
                DICT_KEY_DEST: destination,
                DICT_KEY_ARRIVAL: arrival_dt.astimezone(HELSINKI).strftime("%H:%M:%S"),
                "arrival_timestamp": arrival_timestamp,
                "arrival_datetime": arrival_dt.isoformat(),
                "scheduled_timestamp": service_day + scheduled,
                "realtime": realtime,
                "delay_seconds": arrival_offset - scheduled,
            }
        )

    routes.sort(key=lambda item: item["arrival_timestamp"])
    return {
        STOP_NAME: stop.get("name") or "",
        STOP_CODE: stop.get("code") or "",
        STOP_GTFS: stop.get("gtfsId") or "",
        "stop_latitude": stop.get("lat"),
        "stop_longitude": stop.get("lon"),
        DICT_KEY_ROUTES: routes,
    }


def upcoming_departures(data: dict | None, now_timestamp: float) -> list[dict]:
    """Return only upcoming journeys, ordered by their actual arrival time.

    The service may return a departure whose real-time prediction has
    already expired. Do not show it as the *next* bus until the next poll.
    This function does not mutate coordinator data.
    """
    departures = (data or {}).get(DICT_KEY_ROUTES) or []
    return sorted(
        (
            item
            for item in departures
            if isinstance(item, dict)
            and isinstance(item.get("arrival_timestamp"), (int, float))
            and item["arrival_timestamp"] >= now_timestamp
        ),
        key=lambda item: item["arrival_timestamp"],
    )



def stop_map_departure_attributes(
    data: dict | None, now_timestamp: float, limit: int = 5
) -> dict:
    """Human-readable next departures in geo_location More Info attributes.

    The coordinator's filtered, already-fetched journeys are the sole data
    source. Never request new data from here. Display local Helsinki clock
    times and the date when an arrival is on another calendar day.
    """
    from .const import DEFAULT_MAP_STOP_DEPARTURES, MAX_MAP_STOP_DEPARTURES

    if type(limit) is not int or not 1 <= limit <= MAX_MAP_STOP_DEPARTURES:
        limit = DEFAULT_MAP_STOP_DEPARTURES
    entries = upcoming_departures(data, now_timestamp)[:limit]
    today = datetime.fromtimestamp(now_timestamp, tz=HELSINKI).date()
    attributes = {"upcoming_departures_count": len(entries)}
    for idx, entry in enumerate(entries, 1):
        arrival = datetime.fromtimestamp(
            entry["arrival_timestamp"], tz=HELSINKI
        )
        when = (
            arrival.strftime("%H:%M")
            if arrival.date() == today
            else arrival.strftime("%d.%m %H:%M")
        )
        route = entry.get("route") or "?"
        destination = entry.get("destination") or "Unknown destination"
        attributes[f"next_departure_{idx}"] = (
            f"{when} · {route} → {destination}"
        )
    return attributes
